class DataProcessor:
    def __init__(self, config):
        self.config = config
        self._transform_cache = {}

    def _get_transform_key(self, item):
        """Return a hashable key for caching. Override for custom types."""
        if isinstance(item, (str, int, float, bool, bytes, tuple)):
            return item
        if isinstance(item, dict):
            return tuple(sorted(item.items()))
        return id(item)

    def _transform(self, item):
        key = self._get_transform_key(item)
        if key in self._transform_cache:
            return self._transform_cache[key]
        transformed = item
        if self.config.get('transform'):
            transformed = self.config['transform'](item)
        self._transform_cache[key] = transformed
        return transformed

    def _filter(self, item):
        if not self.config.get('filter'):
            return True
        return self.config['filter'](item)

    def process(self, data):
        result = []
        for item in data:
            if not self._filter(item):
                continue
            result.append(self._transform(item))
        return result

